import * as THREE from 'three/webgpu';
import { texture, uv, vec4, uniform } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-2-label';

  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/cta-hero-isolated.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const opacityUniform = uniform(1.0);
  const uvNode = uv();
  const texNode = texture(map, uvNode);
  material.colorNode = vec4(texNode.rgb, texNode.a.mul(opacityUniform));

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'pricing-card-2-label-plane';
  group.add(plane);

  let textMesh = null;
  try {
    textMesh = createTextMesh(ctx.fontAtlas, {
      text: 'Pricing 3',
      role: 'headline',
      font: 'Lora',
      weight: 400,
      sizePx: 39,
      color: config?.visualSpec?.colors?.paper || '#e8ecf2',
      align: 'center',
      anchor: 'center',
      maxWidth: width * 0.9,
    });
    textMesh.position.set(0, 0, 0.001);
    group.add(textMesh);
  } catch (e) {
    // font atlas unavailable — plane still renders
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) {
        if (Array.isArray(textMesh.material)) {
          textMesh.material.forEach((m) => m.dispose());
        } else {
          textMesh.material.dispose();
        }
      }
    }
  };

  return group;
}
